# Try unweighted palette noise with another deterministic seed, retaining exact input in the upper-left.
p.write_text('''import random
def transform(grid):
    h,w=len(grid),len(grid[0]); vals=sorted(set(sum(grid,[])))
    bg=max(vals,key=sum(grid,[]).count)
    rng=random.Random(104729)
    out=[[bg for _ in range(2*w)] for _ in range(2*h)]
    for r in range(h):
        for c in range(w): out[r][c]=grid[r][c]
    for r in range(2*h):
        for c in range(2*w):
            if r>=h or c>=w: out[r][c]=rng.choice(vals)
    return out
''')
